 1	predicate IsOdd(x: int)
 2	{
 3	    x % 2 != 0
 4	}
 5	
 6	method FindFirstOdd(a: array<int>) returns (found: bool, index: int)
 7	    requires a != null
 8	    ensures !found ==> forall i :: 0 <= i < a.Length ==> !IsOdd(a[i])
 9	    ensures found ==> 0 <= index < a.Length && IsOdd(a[index]) && forall i :: 0 <= i < index ==> !IsOdd(a[i])
10	{
11	    found := false;
12	    index := 0;
13	    while (index < a.Length)
14	        invariant 0 <= index <= a.Length
15	        invariant found ==> IsOdd(a[index - 1]) && forall i :: 0 <= i < index - 1 ==> !IsOdd(a[i])
16	    {
17	        if IsOdd(a[index])
18	        {
19	            found := true;
20	            return;
21	        }
22	        index := index + 1;
23	    }
24	}

